<template>
  <details class="wallet-profile" :open="expanded" @toggle="expanded=$event.target.open">
    <summary>{{ tr('钱包查询','Wallet lookup') }} <span>{{ tr('只读公开持仓','Read public holdings') }}</span></summary>
    <p class="wallet-note">{{ tr('粘贴地址查看持仓，无需连接或签名。本次浏览保留查询，主动保存后地址才会与账号关联。','Paste an address to inspect holdings without connecting or signing. Queries remain in this browsing session; only an explicit save links an address to your account.') }}</p>
    <p v-if="capabilityState==='loading'" class="wallet-note" role="status">{{ tr('正在读取持仓来源…','Loading holdings sources…') }}</p>
    <p v-else-if="capabilityState==='error'" class="wallet-error" role="alert">{{ tr('持仓来源读取失败。','Holdings sources could not be loaded.') }} <button type="button" @click="loadCapabilities">{{ tr('重试','Retry') }}</button></p>
    <div v-if="capabilities" class="chain-coverage"><span v-for="chain in capabilities.chains" :key="chain.chainId" :class="{uncovered:!chain.available}">{{ chain.label }} · {{ chain.available?tr('已覆盖','Covered'):tr('未覆盖','Not covered') }}</span></div>
    <p v-if="capabilities&&!capabilities.available" class="wallet-note">{{ tr('当前尚未接通持仓来源。未覆盖不表示没有持仓。','Holdings sources are not connected. An uncovered chain does not mean an empty wallet.') }}</p>
    <form v-else @submit.prevent="query"><label :for="inputId">{{ tr('公开钱包地址','Public wallet address') }}</label><div class="wallet-query"><input :id="inputId" v-model.trim="address" :disabled="busy" placeholder="0x…" autocomplete="off" spellcheck="false" maxlength="42" pattern="0x[a-fA-F0-9]{40}" required><button :disabled="busy || !capabilities?.available">{{ busy?tr('查询中…','Querying…'):tr('查看持仓','View holdings') }}</button></div></form>
    <p v-if="selectionLabel && address===selectedAddress" class="wallet-note" role="status">{{ tr('已选择地址：','Selected address: ') }} {{ selectionLabel }} · {{ tr('点击“查看持仓”进行查询。','Choose View holdings to query it.') }}</p>
    <p v-if="error" role="alert" class="wallet-error">{{ error }}</p>
    <template v-if="profile">
      <div class="wallet-total"><span>{{ tr('站内可估值持仓（USD）','Holdings valued by this site (USD)') }} · <code :title="profile.address">{{ short(profile.address) }}</code></span><strong :title="tr('使用站内可用报价估值的持仓合计（USD），不包含未估值资产及未覆盖链','Holdings valued using available site quotes (USD), excluding unvalued assets and uncovered chains')">{{ usd(profile.metrics.totalValueUsd) }}</strong><small>{{ date(profile.at) }} · {{ tr('未估值与未覆盖链不计入总值','Unvalued assets and uncovered chains are excluded') }}</small></div>
      <div class="wallet-metrics"><span><strong :title="tr('钱包覆盖的股票主题数 / 站内有效股票主题总数','Stock themes covered by this wallet / effective stock themes on the site')">{{ profile.metrics.themeCoverage }} / {{ profile.metrics.effectiveThemeCount }}</strong>{{ tr('主题覆盖','Theme coverage') }}</span><span><strong :title="tr('已估值金额不少于10美元的持仓数量','Valued holdings worth at least 10 USD')">{{ profile.metrics.effectiveHoldingCount }}</strong>{{ tr('≥ $10 的持仓','Holdings ≥ $10') }}</span><span><strong :title="tr('各主题价值占可估值总值比例的平方和；多主题持仓均分价值，缺失不表示零','Sum of squared theme shares of valued holdings; multi-theme holdings split value equally, missing does not mean zero')">{{ profile.metrics.themeHHI==null?'—':profile.metrics.themeHHI.toFixed(3) }}</strong>{{ tr('主题集中度 HHI','Theme concentration HHI') }}</span><span><strong :title="tr('已提示风险的持仓价值 / 可估值持仓总值；未检测风险未当作安全','Value of flagged holdings / total valued holdings; unchecked risk is not treated as safe')">{{ percent(profile.metrics.riskValueShare) }}</strong>{{ tr('风险敞口','Flagged exposure') }}</span></div>
      <p v-for="line in profile.summary" :key="line" class="wallet-summary">{{ line }}</p>
      <div v-if="profile.themes.length" class="wallet-themes"><h3>{{ tr('主题分布','Theme distribution') }}</h3><RouterLink v-for="theme in profile.themes" :key="theme.ticker" :to="themeNavigationLink(theme.ticker,{route,scope})"><span>{{ theme.ticker }}</span><i><b :style="{width:100*theme.share+'%'}"></b></i><strong :title="tr('此主题价值占可估值持仓总值的比例','This theme’s share of total valued holdings')">{{ percent(theme.share) }}</strong></RouterLink></div>
      <div class="wallet-holdings"><h3>{{ tr('持仓与退出冲击','Holdings and exit impact') }}</h3><article v-for="holding in profile.holdings" :key="holding.chainId+holding.token"><div><RouterLink :to="assetNavigationLink(holding,{route,scope})"><strong>{{ holding.symbol || short(holding.token) }}</strong></RouterLink><small>{{ holding.name }} · {{ tr('数量','Quantity') }} {{ holding.quantity }} · {{ chainName(holding) }}</small><span v-if="holding.riskFlag" class="wallet-risk">{{ tr('有风险提示','Risk flagged') }}</span><span v-else-if="holding.riskUnknown" class="wallet-note">{{ tr('风险未能完整识别','Risk checks incomplete') }}</span></div><div class="holding-values"><small>{{ tr('持仓估值（USD）','Holding value (USD)') }}</small><strong :title="tr('持仓数量与可用美元报价计算的估值','Value computed from holding quantity and an available USD quote')">{{ usd(holding.valueUsd) }}</strong><small :title="tr('占可估值持仓总值的比例','Share of total valued holdings')">{{ tr('价值占比','Value share') }} {{ percent(holding.share) }}</small><span v-if="holding.exitImpact?.valuePercent!=null" :title="tr('支持的V2池内卖出全部持仓的估算价格冲击（%）；未知税费与MEV未计入','Estimated sell-all price impact in supported V2 pools (%), excluding unknown taxes and MEV')" :class="{'wallet-risk':holding.exitImpact.valuePercent>10}">{{ tr('全部卖出冲击约','Approx. sell-all impact') }} {{ holding.exitImpact.valuePercent.toFixed(2) }}%</span><span v-else>{{ tr('退出冲击未计算','Exit impact unavailable') }}</span></div></article><p v-if="!profile.holdings.length" class="wallet-note">{{ tr('已覆盖链没有可用站内价格的持仓；请查看下方未估值列表。','No holdings on covered chains have a usable site price. See unvalued assets below.') }}</p></div>
      <details v-if="profile.unvalued.length" class="wallet-unvalued" :open="unvaluedOpen" @toggle="unvaluedOpen=$event.target.open"><summary>{{ tr('未估值','Unvalued') }} {{ profile.unvalued.length }}</summary><div v-for="holding in profile.unvalued" :key="holding.chainId+holding.token"><strong>{{ holding.symbol || short(holding.token) }}</strong><span>{{ holding.quantity || tr('数量未读取','Quantity unavailable') }}</span><small>{{ holding.chainId }} · {{ short(holding.token) }}</small></div></details>
      <p class="wallet-note">{{ tr('HHI 按主题价值占可估值总值的比例计算，多主题持仓均分价值。仅支持的 V2 池计算冲击，未知税费与 MEV 未计入。','HHI uses each theme’s share of valued holdings; multi-theme holdings split value equally. Impact covers supported V2 pools and excludes unknown taxes and MEV.') }}</p>
      <form v-if="account.session" class="wallet-save" @submit.prevent="save"><label>{{ tr('保存名称（可选）','Saved label (optional)') }}<input v-model.trim="label" maxlength="60"></label><label class="consent"><input v-model="consent" type="checkbox">{{ tr('同意将此公开地址保存到我的账号，可随时删除。','Save this public address to my account. It can be deleted anytime.') }}</label><button :disabled="busy || !consent">{{ tr('保存到我的','Save to account') }}</button><span v-if="saved">{{ tr('已保存','Saved') }}</span></form><RouterLink v-else :to="{path:'/me',query:{chain:scope}}">{{ tr('登录后可主动保存地址','Sign in to save an address') }} →</RouterLink>
    </template>
    <div v-if="account.session" class="saved-wallet-state"><p v-if="savedState==='loading'" class="wallet-note" role="status">{{ tr('正在读取已保存地址…','Loading saved addresses…') }}</p><p v-else-if="savedState==='error'" class="wallet-error" role="alert">{{ tr('已保存地址读取失败。','Saved addresses could not be loaded.') }} <button type="button" @click="loadSaved">{{ tr('重试','Retry') }}</button></p><p v-else-if="savedState==='ready'&&!savedWallets.length" class="wallet-note">{{ tr('尚未保存地址。','No saved addresses yet.') }}</p></div>
    <div v-if="savedWallets.length" class="saved-wallets"><h3>{{ tr('已保存的地址','Saved addresses') }}</h3><div v-for="wallet in savedWallets" :key="wallet.address"><button type="button" :disabled="busy" @click="selectSaved(wallet)">{{ tr('选择地址','Select address') }} · {{ wallet.label || short(wallet.address) }}</button><code>{{ short(wallet.address) }}</code><button type="button" :disabled="busy" @click="remove(wallet.address)">{{ tr('删除','Delete') }}</button></div></div>
  </details>
</template>
<script setup>
import { computed, ref, onMounted, onUnmounted, watch, useId } from 'vue';
import { useRoute } from 'vue-router';
import { assetNavigationLink, themeNavigationLink } from '../utils/navigation-context';
import { readPageState, writePageState, clearPageState } from '../utils/page-navigation-state';
import { chainScope } from '../utils/chain-scope';
import { productRequest } from '../api/developer';
import { useAccountStore } from '../stores/account';
import { tr } from '../i18n';
import { usd,date,short,chainName } from '../utils/format';
const account=useAccountStore(),inputId=useId(),route=useRoute();
const scope=computed(()=>chainScope(route.query));
const stateKey=()=>`wallet-profile:${account.session?.user.id??'guest'}`;
const restored=readPageState(stateKey())??{};
const capabilities=ref(null),address=ref(typeof restored.address==='string'?restored.address:''),label=ref(typeof restored.label==='string'?restored.label:''),consent=ref(false),profile=ref(restored.profile??null),savedWallets=ref([]),busy=ref(false),error=ref(''),saved=ref(false),expanded=ref(restored.expanded===true),unvaluedOpen=ref(restored.unvaluedOpen===true);
const savedState=ref('idle'),capabilityState=ref('loading'),selectionLabel=ref(''),selectedAddress=ref('');
let queryRequest=0,savedRequest=0,mutationRequest=0,capabilityRequest=0;
let accountObserved=false;
let stateOwner=account.session?.user.id??'guest';
function persistPage(){if(stateOwner!==(account.session?.user.id??'guest'))return;writePageState(stateKey(),{address:address.value,label:label.value,profile:profile.value,expanded:expanded.value,unvaluedOpen:unvaluedOpen.value});}
watch([address,label,profile,expanded,unvaluedOpen],persistPage);
onUnmounted(persistPage);
const percent=value=>value==null?'—':(100*value).toFixed(1)+'%';
function failure(e){return e.message==='invalid-wallet-address'?tr('请输入 0x 开头的 42 位地址。','Enter a 42-character address starting with 0x.'):e.status===429?tr('请稍后再查询。','Wait a moment before querying again.'):tr('暂时无法读取，请重试。','Could not load. Please retry.');}
async function query(){const owner=account.session?.user.id,request=++queryRequest;busy.value=true;error.value='';profile.value=null;saved.value=false;consent.value=false;try{const result=await productRequest('wallet/profile',{method:'POST',body:{address:address.value}});if(request===queryRequest&&account.session?.user.id===owner){profile.value=result;persistPage();}}catch(e){if(request===queryRequest&&account.session?.user.id===owner)error.value=failure(e);}finally{if(request===queryRequest)busy.value=false;}}
async function loadSaved(){const id=account.session?.user.id,request=++savedRequest;if(!id){savedState.value='idle';return;}savedState.value='loading';try{const result=await productRequest('wallet/saved');if(request===savedRequest&&account.session?.user.id===id){savedWallets.value=result.items;savedState.value='ready';}}catch{if(request===savedRequest&&account.session?.user.id===id)savedState.value='error';}}
async function loadCapabilities(){const request=++capabilityRequest;capabilityState.value='loading';try{const result=await productRequest('capabilities');if(request===capabilityRequest){capabilities.value=result.wallet;capabilityState.value='ready';}}catch{if(request===capabilityRequest)capabilityState.value='error';}}
async function save(){const userId=account.session?.user.id;if(!userId||!profile.value||busy.value)return;const request=++mutationRequest;busy.value=true;error.value='';try{const result=await productRequest('wallet/saved',{method:'POST',csrfToken:account.session.csrfToken,body:{address:profile.value.address,label:label.value,consent:consent.value}});if(request===mutationRequest&&account.session?.user.id===userId){savedWallets.value=result.items;savedState.value='ready';saved.value=true;}}catch(e){if(request===mutationRequest&&account.session?.user.id===userId)error.value=failure(e);}finally{if(request===mutationRequest)busy.value=false;}}
async function remove(value){const userId=account.session?.user.id;if(!userId||busy.value)return;const request=++mutationRequest;busy.value=true;error.value='';try{const result=await productRequest('wallet/saved/'+encodeURIComponent(value),{method:'DELETE',csrfToken:account.session.csrfToken});if(request===mutationRequest&&account.session?.user.id===userId){savedWallets.value=result.items;savedState.value='ready';}}catch(e){if(request===mutationRequest&&account.session?.user.id===userId)error.value=failure(e);}finally{if(request===mutationRequest)busy.value=false;}}
function selectSaved(wallet){if(busy.value)return;address.value=wallet.address;label.value=wallet.label;profile.value=null;consent.value=false;saved.value=false;selectionLabel.value=wallet.label||short(wallet.address);selectedAddress.value=wallet.address;}
watch(()=>account.session?.user.id,async(id,previous)=>{
  ++savedRequest;++mutationRequest;savedState.value='idle';savedWallets.value=[];selectionLabel.value='';
  const changed=accountObserved&&id!==previous;accountObserved=true;
  if(changed){clearPageState(`wallet-profile:${previous??'guest'}`);clearPageState('wallet-profile:guest');}
  if(changed){
    ++queryRequest;busy.value=false;error.value='';consent.value=false;saved.value=false;
    const value=readPageState(stateKey())??{};address.value=value.address??'';label.value=value.label??'';profile.value=value.profile??null;expanded.value=value.expanded===true;unvaluedOpen.value=value.unvaluedOpen===true;
    stateOwner=id??'guest';
  }
  if(id)loadSaved();
},{immediate:true});
onMounted(loadCapabilities);
onUnmounted(()=>{++queryRequest;++savedRequest;++mutationRequest;++capabilityRequest;});
</script>
<style scoped>
.wallet-profile{padding:24px 0;border-top:1px solid var(--border);font-size:13px}.wallet-profile>summary{cursor:pointer;font-family:var(--display-font);font-size:20px}.wallet-profile>summary>span{margin-left:16px;color:var(--muted);font-family:var(--font-body, sans-serif);font-size:12px}.wallet-note{color:var(--muted);font-size:12px;line-height:1.7}.chain-coverage{display:flex;flex-wrap:wrap;gap:8px 14px;margin:16px 0;color:var(--text)}.chain-coverage .uncovered{color:var(--muted)}.wallet-query{display:flex;gap:8px;margin-top:8px}.wallet-query input{flex:1;min-width:0}.wallet-profile input:not([type=checkbox]){padding:10px 12px;border:1px solid var(--border);background:transparent;color:var(--text);font:inherit}.wallet-profile button{padding:9px 16px;border:1px solid var(--border);background:transparent;color:var(--text);font:inherit;cursor:pointer}.wallet-profile button:disabled{opacity:.5;cursor:wait}.wallet-error{color:var(--loss)}.wallet-total{margin:24px 0;display:grid;gap:9px}.wallet-total>strong{font-size:42px;font-weight:500;font-variant-numeric:tabular-nums}.wallet-total>small{font-size:12px;color:var(--muted)}.wallet-metrics{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid var(--border);padding:16px 0;gap:12px}.wallet-metrics>span{display:grid;gap:10px;color:var(--muted);font-size:12px}.wallet-metrics strong{font-size:21px;color:var(--text);font-weight:500}.wallet-summary{line-height:1.8}.wallet-profile h3{font-weight:500;font-size:14px;margin:22px 0 12px}.wallet-themes>a{display:grid;grid-template-columns:70px 1fr 70px;align-items:center;gap:12px;color:var(--text);padding:10px 0}.wallet-themes i{height:5px;background:var(--border);overflow:hidden}.wallet-themes b{display:block;height:100%;background:var(--accent)}.wallet-themes strong{text-align:right;font-weight:500}.wallet-holdings article{display:flex;justify-content:space-between;gap:20px;padding:17px 0;border-top:1px solid var(--border)}.wallet-holdings article>div{display:grid;gap:6px}.wallet-holdings a{color:var(--text);text-decoration:underline;text-underline-offset:4px}.wallet-holdings small{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.holding-values{text-align:right;min-width:125px}.holding-values>span{font-size:12px}.wallet-risk{color:var(--warning);font-size:12px}.wallet-unvalued{padding:15px 0;border-top:1px solid var(--border)}.wallet-unvalued summary{cursor:pointer}.wallet-unvalued>div{display:flex;gap:12px;flex-wrap:wrap;padding:12px 0}.wallet-unvalued small{color:var(--muted);font-size:12px}.wallet-save{display:grid;gap:12px;margin:20px 0}.wallet-save label:not(.consent){display:grid;gap:8px}.wallet-save .consent{display:flex;gap:10px;font-size:12px;line-height:1.7}.wallet-save button{width:max-content}.saved-wallets>div{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--border)}.saved-wallets>div button:last-child{margin-left:auto}.saved-wallets code{font-size:12px;color:var(--muted)}@media(max-width:600px){.wallet-query{flex-direction:column}.wallet-metrics{grid-template-columns:repeat(2,1fr);gap:20px 12px}.wallet-total>strong{font-size:34px}.wallet-holdings article{gap:12px}.holding-values{min-width:112px}.saved-wallets>div{flex-wrap:wrap}.wallet-profile>summary>span{display:block;margin:8px 0 0 18px}}
</style>
